    integrity = {"required_paths": {str(p): p.exists() for p in required}, "all_required_paths_exist": all(p.exists() for p in required), "json_parse_check": True, "superseded_first_pass": {"metrics": [str(OUT / "metrics" / f"ranker_f{f}.json") for f in range(4)], "reason": "candidate parent metadata was history-major while boxes were transform-major", "used_for_decision": False}, "checkpoint_hashes": {str(OUT / "checkpoints" / f"ranker_ordered_f{f}_best.pt"): sha256(OUT / "checkpoints" / f"ranker_ordered_f{f}_best.pt") for f in range(4)}, "source_hashes": {"corrected_csv": stage0["source_csv_sha256"], "feature_npz": stage0["feature_sha256"]}}
