    public_scan = {"path_name_hits": [x for x in output_names if any(t in x for t in ("q1", "devplus", "new_model", "public_labels"))], "sealed": True, "note": "metadata fields listing sealed inputs are not labels"}
    decision = {"protocol": "trackocd_iclr27_phase23_proposal_source_replacement", "execution_time": dt.datetime.now(dt.timezone.utc).isoformat(), "decision_code": "P23_GATE_P2_FAIL_STOP_BEFORE_CORRESPONDENCE", "git": git_state(), "phase22_invalid_visual_conclusion_due_to_key_bug": True, "phase22_first_actionable_root_cause": {"feature_row_key_mismatch": stage0["feature_row_key_mismatch_count"], "positional_match": stage0["feature_key_alignment"]["positional_match_count"], "set_overlap": stage0["feature_key_alignment"]["set_overlap_count"], "aligned_exact": stage0["feature_key_alignment"]["aligned_exact_count"], "geometry_errors": stage0["geometry_consistency"], "affected_events": stage0["feature_alignment_event_impact"]["events_with_any_mismatch"], "affected_folds": stage0["feature_alignment_event_impact"]["folds_with_any_mismatch"], "repair": "Phase23 in-memory key permutation; Phase22 files untouched"}, "alignment_regression": {"raw_prefix16": align["raw_baseline_prefix16"]["ceiling_correct"], "identity_preserves_raw": align["identity_refiner_preserves_raw_ceiling"], "targeted_fold": align["targeted_fold"]}, "stage0": {"rows": stage0["rows"], "raw_gt_iou_bins": stage0["raw_gt_iou_row_bins"], "event_side_bins": stage0["event_side_raw_max_iou_bins"], "label_statistics": stage0["phase22_label_statistics"], "decision": "geometry/chronology clean; candidate pool authorized after loader alignment repair"}, "stage1": {"prefix16_raw": stage1["prefix16"]["raw_ceiling"], "prefix16_candidate_pool_oracle": stage1["prefix16"]["candidate_pool_ceiling"], "source_reliable": stage1["prefix16"]["source_reliable_events"], "target_reliable": stage1["prefix16"]["target_reliable_events"], "by_fold": stage1["prefix16"]["by_fold"], "train_recall": stage1["train_gt_candidate_recall"], "next_branch": stage1["stage2_branch"], "candidate_gate": stage1["gate_o_candidate_pool"]}, "stage2": {"branch": "quality_ranker", "tag": "ordered", "config": str(ROOT / "configs/iclr27_phase23/stage2a_ranker.json"), "fold_metrics": [{"fold": d["fold"], "steps": d["steps"], "fit_rows": d["fit_rows"], "fit_candidates": d["fit_candidates"], "validation_rows": d["validation_rows"], "validation_candidates": d["validation_candidates"], "validation_metrics": d["validation_metrics"], "best_step": d["best_step"], "checkpoint": d["checkpoint_best"]} for d in rankers], "source_branch": "not authorized because candidate-pool oracle met the Stage2A condition", "domain_branch": "skipped; no causal domain evidence was registered"}, "stage3": {"prefix16": {c: p16[c] for c in conditions}, "persistent_controller": "not run; proposal Gate P2 failed before correspondence/controller reconnect"}, "gate_p2": stage3["gate_p2"], "public_q1": {"accessed": False, "sealed": ["DEV+", "Q1", "public new-model labels"]}, "resources": cfg["resource_preflight"], "symlinks": symlinks, "integrity": integrity, "residual_phase23_process_check": "clean at finalization (long supervisors exited; only read-only finalizer command was active)", "limitations": ["candidate-pool oracle is diagnostic and cannot be used as a learned proposal result", "quality ranker selected only 21/76 despite 38/76 candidate coverage", "Phase22 positional feature bug makes its 3/76 refiner result invalid as a visual-learning conclusion"], "next_direction": "replace/repair the DSCT proposal source or train a source/candidate generator with key-aligned supervision; only after a real proposal model passes Gate P2 should correspondence/controller be revisited"}
