    lines += ["", "## Stage 3 — true-IoU 76-event validation", "", "Only the frozen true-IoU proposal protocol is decisive.  `candidate_pool_oracle` and `gt_tight_oracle` are diagnostics, not learned results; ranker uses top-5 candidates per row and the same assigned-parent rule.", "", "| condition | prefix16 source | prefix16 target | ceiling | category coverage | video coverage |", "|---|---:|---:|---:|---:|---:|"]
    for c in conditions: lines.append(f"| {c} | {p16[c]['source_reliable_events']} | {p16[c]['target_reliable_events']} | {p16[c]['ceiling_correct']}/76 | {p16[c]['category_coverage']} | {p16[c]['video_coverage']} |")
    lines += ["", "### Prefix comparison", "", "| condition | p1 | p2 | p4 | p8 | p16 |", "|---|---:|---:|---:|---:|---:|"]
